"use client"

import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import type { Recipient } from "../schema"

function initials(name: string) {
  return name
    .split(" ")
    .map((part) => part[0])
    .slice(0, 2)
    .join("")
    .toUpperCase()
}

export function RecipientRow({
  recipient,
  onSelect,
}: {
  recipient: Recipient
  onSelect: () => void
}) {
  return (
    <Card variant="outlined" size="sm" interactive onClick={onSelect}>
      <CardContent>
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
          <div
            style={{
              width: "var(--atlas-spacing-10)",
              height: "var(--atlas-spacing-10)",
              flexShrink: 0,
              borderRadius: "var(--atlas-radius-full)",
              background: "var(--atlas-primary-subtle)",
              color: "var(--atlas-primary)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: "var(--atlas-text-body-sm)",
              fontWeight: "var(--atlas-font-weight-semibold)",
            }}
            aria-hidden="true"
          >
            {initials(recipient.name)}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div
              style={{
                fontSize: "var(--atlas-text-body)",
                fontWeight: "var(--atlas-font-weight-medium)",
                color: "var(--atlas-foreground)",
              }}
            >
              {recipient.name}
            </div>
            <div style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>
              {recipient.account}
            </div>
          </div>
          <Badge variant="secondary" size="sm">
            {recipient.currency}
          </Badge>
        </div>
      </CardContent>
    </Card>
  )
}

export function SummaryRow({ label, value, strong }: { label: string; value: string; strong?: boolean }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", fontSize: "var(--atlas-text-body-sm)" }}>
      <span style={{ color: "var(--atlas-foreground-muted)" }}>{label}</span>
      <span
        style={{
          fontWeight: strong ? "var(--atlas-font-weight-semibold)" : "var(--atlas-font-weight-regular)",
          color: "var(--atlas-foreground)",
        }}
      >
        {value}
      </span>
    </div>
  )
}

