"use client"

import { useState } from "react"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RECENT_RECIPIENTS } from "../schema"
import { RecipientRow } from "./_parts"
import type { SendMoneyStepProps } from "../schema"

export function Recipient({ patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")
  const filtered = RECENT_RECIPIENTS.filter((r) =>
    r.name.toLowerCase().includes(query.trim().toLowerCase()),
  )

  const select = (r: (typeof RECENT_RECIPIENTS)[number]) => {
    patch({
      recipientId: r.id,
      recipientName: r.name,
      recipientAccount: r.account,
      recipientCurrency: r.currency,
    })
    next()
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
      }}
    >
      <div>
        <Label htmlFor="recipient-search" size="sm">
          Search recipients
        </Label>
        <Input
          id="recipient-search"
          variant="default"
          size="md"
          placeholder="Name or account"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <div>
        <div
          style={{
            fontSize: "var(--atlas-text-caption)",
            color: "var(--atlas-foreground-muted)",
            marginBlockEnd: "var(--atlas-spacing-2)",
            textTransform: "uppercase",
            letterSpacing: "var(--atlas-letter-spacing-wide)",
          }}
        >
          Recent recipients
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
          {filtered.length === 0 ? (
            <div style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
              No recipients match &ldquo;{query}&rdquo;.
            </div>
          ) : (
            filtered.map((r) => <RecipientRow key={r.id} recipient={r} onSelect={() => select(r)} />)
          )}
        </div>
      </div>
    </div>
  )
}

